<script>
    $(document).on("click", "#hireFreelancerBtn", function(e) {

        e.preventDefault();

        let conversationId = $("#conversation-id").val();

        $.ajax({

            url: "{{ route('chat.hire.request') }}",
            type: "POST",

            data: {

                _token: "{{ csrf_token() }}",
                conversation_id: conversationId

            },

            beforeSend: function() {

                $("#hireFreelancerBtn")
                    .text("Sending...")
                    .css("pointer-events", "none");

            },

            success: function(res) {

                if (res.status) {

                    alert(res.message); 
                    $("#hireyou").remove();

                } else {

                    alert(res.message);

                    $("#hireFreelancerBtn")
                        .html("<span>I Want to Hire You</span>")
                        .css("pointer-events", "auto");

                }

            },

            error: function() {

                alert("Something went wrong.");

                $("#hireFreelancerBtn")
                    .html("<span>I Want to Hire You</span>")
                    .css("pointer-events", "auto");

            }

        });

    });
</script>